import { CartItem } from './cart-item';
import { Product } from './product';

describe('CartItem', () => {
  const mockProduct = { id: 1, name: "Test Product", unitPrice: 10.99 } as unknown as Product;
expect(new CartItem(mockProduct)).toBeTruthy();

});
